// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
return `rgba(255, 255, 255, ${titleBarOpacity})`

// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
const a = 255 * (1 - titleBarOpacity)
return `rgb(${a}, ${a}, ${a})`

// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
return titleBarOpacity > 0.5 ? 'black' : 'white'
